spec.setup_code:
camera.position.set(0, 1.4, 5);
scene.background = new THREE.Color('#fafafa');
scene.add(new THREE.AmbientLight(0xffffff, 0.7));
var dl = new THREE.DirectionalLight(0xffffff, 0.9); dl.position.set(3, 5, 4); scene.add(dl);
var mat = function (c) { return new THREE.MeshStandardMaterial({ color: c }); };
var la = new THREE.Mesh(new THREE.SphereGeometry(0.55, 32, 32), mat('#e11d48')); la.position.set(0.55, 0.7, 0); group.add(la);
var ra = new THREE.Mesh(new THREE.SphereGeometry(0.55, 32, 32), mat('#2563eb')); ra.position.set(-0.55, 0.7, 0); group.add(ra);
var lv = new THREE.Mesh(new THREE.ConeGeometry(0.7, 1.6, 32), mat('#be123c')); lv.position.set(0.4, -0.5, 0); lv.rotation.z = Math.PI + 0.2; group.add(lv);
var rv = new THREE.Mesh(new THREE.ConeGeometry(0.6, 1.4, 32), mat('#1d4ed8')); rv.position.set(-0.4, -0.45, 0.1); rv.rotation.z = Math.PI - 0.2; group.add(rv);
var ao = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.14, 16, 40, Math.PI), mat('#f43f5e')); ao.position.set(0.2, 1.4, 0); group.add(ao);
var pa = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.8, 16), mat('#3b82f6')); pa.position.set(-0.3, 1.5, 0.2); group.add(pa);
return { update: function (t) { var s = 1 + Math.max(0, Math.sin(t * 7.5)) * 0.06; lv.scale.set(s, s, s); rv.scale.set(s, s, s); group.rotation.y = t * 0.4; } };

var title = "Pacemaker depolarisation";
return { draw: function (ctx, w, h, time) {
  ctx.fillStyle = '#fafafa'; ctx.fillRect(0, 0, w, h);
  var T = 4, tt = time % T; var ox = 50, oy = h - 40, W = w - 80, H = h - 90;
  ctx.strokeStyle = '#9ca3af'; ctx.beginPath(); ctx.moveTo(ox, 30); ctx.lineTo(ox, oy); ctx.lineTo(ox + W, oy); ctx.stroke();
  function v(s) { if (s < 1) return -70; if (s < 1.15) return -70 + (s - 1) / 0.15 * 15; if (s < 1.35) return -55 + (s - 1.15) / 0.2 * 95; if (s < 1.7) return 40 - (s - 1.35) / 0.35 * 120; if (s < 2.4) return -80 + (s - 1.7) / 0.7 * 10; return -70; }
  function Y(mv) { return oy - (mv + 90) / 140 * H; }
  ctx.strokeStyle = '#e11d48'; ctx.lineWidth = 2; ctx.beginPath();
  for (var i = 0; i <= 300; i++) { var s = i / 300 * T; if (s > tt) break; var x = ox + s / T * W; if (i === 0) ctx.moveTo(x, Y(v(s))); else ctx.lineTo(x, Y(v(s))); } ctx.stroke();
  ctx.setLineDash([5, 4]); ctx.strokeStyle = '#d97706'; ctx.beginPath(); ctx.moveTo(ox, Y(-55)); ctx.lineTo(ox + W, Y(-55)); ctx.stroke(); ctx.setLineDash([]);
  ctx.fillStyle = '#1a1a1d'; ctx.font = '14px sans-serif'; ctx.fillText(title, 14, 20); ctx.font = '12px sans-serif'; ctx.fillText('threshold -55 mV', ox + W - 110, Y(-55) - 6); ctx.fillText('Vm (mV)', 8, 44); ctx.fillText('time (ms)', ox + W - 60, oy + 18);
} };

camera.position.set(0, 1.4, 5);
scene.background = new THREE.Color('#fafafa');
scene.add(new THREE.AmbientLight(0xffffff, 0.7));
var dl = new THREE.DirectionalLight(0xffffff, 0.9); dl.position.set(3, 5, 4); scene.add(dl);
var mem = new THREE.Mesh(new THREE.SphereGeometry(2, 48, 48), new THREE.MeshStandardMaterial({ color: '#fda4af', transparent: true, opacity: 0.25 }));
group.add(mem);
var nuc = new THREE.Mesh(new THREE.SphereGeometry(0.7, 32, 32), new THREE.MeshStandardMaterial({ color: '#7c3aed' }));
group.add(nuc);
for (var i = 0; i < 9; i++) {
  var m = new THREE.Mesh(new THREE.CapsuleGeometry(0.12, 0.35, 6, 12), new THREE.MeshStandardMaterial({ color: '#f59e0b' }));
  var a = i * 0.7, r = 1.25 + (i % 3) * 0.18;
  m.position.set(Math.cos(a) * r, Math.sin(a * 1.3) * 0.8, Math.sin(a) * r);
  m.rotation.set(a, a * 0.5, 0); group.add(m);
}
for (var j = 0; j < 14; j++) {
  var ch = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.5, 10), new THREE.MeshStandardMaterial({ color: '#059669' }));
  var th = j / 14 * Math.PI * 2;
  ch.position.set(Math.cos(th) * 2, Math.sin(th * 2) * 0.3, Math.sin(th) * 2);
  ch.lookAt(0, 0, 0); ch.rotateX(Math.PI / 2); group.add(ch);
}
return { update: function (t) { group.rotation.y = t * 0.3; nuc.scale.setScalar(1 + Math.sin(t * 2) * 0.03); } };
